      "sourceUiVerification": {
        "checkedAt": "2026-11-23 23:30",
        "surface": "亲小禾小程序通知模板详情",
        "title": "小朋友挑食怎么办？",
        "source": "系统模板",
        "articleCover": "013_小朋友挑食怎么办/013-diet-hero.png",
        "bodyImageBlockCount": 2,
        "inlineImageCount": 1,
        "status": "正文与2个图片块顺序复核通过，缓存原图匹配"
      },
      "sourceCardFrame": "V17_card_013.png",
      "blocks": [
        {
          "type": "image",
          "role": "食物金字塔插图",
          "text": "",
          "assetRef": "013_小朋友挑食怎么办/013-food-pyramid.png",
          "assetUrl": "assets/notification-mini/template-originals/tpl-013-block-1.png",
          "assetState": "matched",
          "assetSha256": "F9D7557520BDE04E65BF7A2309E8A05912BF0428AAE62B863687CB3E7F818A7C",
          "sourceIncomplete": false,
          "sourceCacheId": "f_000168",
          "sourceDimensions": "551x500",
          "sourceBytes": 41130
        },
        {
          "type": "text",
          "role": "",
          "text": "孩子是每个家庭的未来，是父母的希望。每个父母都希望自己的孩子能健康成长。挑食不利于孩子健康成长。儿童挑食怎么办呢？\n\n很多孩子或多或少都存在挑食的问题，如果孩子挑食，家长要正确对待，不要太过焦虑，可以从以下方面应对:\n\n1、给孩子与之年龄相应份量的食物，不要过多。份量过多，孩子吃不完，会打击他们的自信心。\n\n2、多选择绿色健康的食物，比如蔬菜水果，不要买过多精细加工的超市食品。",
          "assetRef": "",
          "assetUrl": "",
          "assetState": "not-applicable",
          "assetSha256": "",
          "sourceIncomplete": false
        },
        {
          "type": "image",
          "role": "儿童健康饮食插图：女孩与食物",
          "text": "",
          "assetRef": "013_小朋友挑食怎么办/013-child-eating-illustration.png",
          "assetUrl": "assets/notification-mini/template-originals/tpl-013-block-3.png",
          "assetState": "matched",
          "assetSha256": "BB20F6B7E661FADF8144C913BF729F6EECCBAA5C19C44BB5B126B38A7A04BDFA",
          "sourceIncomplete": false,
          "sourceCacheId": "f_000166",
          "sourceDimensions": "719x500",
          "sourceBytes": 59735
        },
        {
          "type": "text",
          "role": "",
          "text": "3、如果可能让孩子也参与到正餐的筹备中，孩子自己参与做的饭菜，更能引起孩子食欲。\n\n4、不要通过奖励的方式让孩子吃东西。\n\n5、对孩子的点滴进步要及时表扬。\n\n6、尽可能全家人一起就餐，避免孩子单独吃饭。另外全家人的饭菜要相同，孩子不要有单独的菜单。\n\n7、少给孩子吃零食，尤其是饭前不要吃零食。\n\n8、家长要以身作则做好榜样，养成良好的饮食习惯，避免挑食。",
          "assetRef": "",
          "assetUrl": "",
          "assetState": "not-applicable",
          "assetSha256": "",
          "sourceIncomplete": false
        }
      ],
      "bodyBlockCount": 4,
      "hasCapturedBodyBlocks": true,
      "pendingImageCount": 0,
      "articleCoverCacheId": "f_000167",
      "articleCoverSourceDimensions": "1500x480",
