          "text": "【放假时间】\nxx年x月x日  -  xx年x月x日（一共放假x天）\n\n【返园时间】x月x日（元气满满地回来上课吧！）\n\n【调课小提醒】\nx月x日（星期x）上课\nx月x日（星期x）上课",
