          "type": "text",
          "role": "",
          "text": "亲爱的家长，您好：\n为方便您为孩子补办校徽，本学期第XX批（XX批次）线上补办现已开启。您可通过【亲小禾】小程序直接办理。\n\n⏰ 关于时间与进度\n1、本次接单截止：XX月XX日\n2、关于到货时间：订单将在截止后统一制作。配送到学校后，我们会第一时间分发至对应班级。（因制作及物流存在不确定因素，但我们会尽快生产配送。）\n3、超时提示：若您在XX月XX日之后提交订单，系统将自动归入下一批次（预计XX月处理）。\n\n📝 办理须知\n1、核对信息：请务必检查学生的年级、班级、姓名是否正确。\n2、修改信息：在XX月XX日截止前，您可随时登录小程序修改照片或班级信息。\n\n👉 如何办理\n1、您可在微信搜索【亲小禾】小程序；或扫描下方二维码，进入【亲小禾】小程序\n2、也可以点击右侧【去首页】按钮返回首页后，再点击红色按钮【立即报名】按钮进行办理",
