          "text": "",
          "assetRef": "亲小禾原图缓存/f_000034",
          "assetUrl": "assets/notification-mini/template-originals/tpl-022-block-1.png",
          "assetState": "cache-filled",
          "assetSha256": "6B1B6E6AD9A2D54EACE8026A7A04BF7676C7DC708EFAC3ABE6A7AB76FA914246",
