          "assetRef": "023_寒潮来袭温馨提示/023-winter-children.png",
          "assetUrl": "assets/notification-mini/template-originals/tpl-023-block-1.png",
          "assetState": "matched",
          "assetSha256": "2717c6442f1d87b2864ef52de9b64982787c72f176be7d3020ce58e8d1fc312f",
