      "sourceUiVerification": null,
      "sourceCardFrame": "V17_card_126.png",
      "blocks": [
        {
          "type": "image",
          "role": "正文标题海报（中秋遇国庆）",
          "text": "",
          "assetRef": "亲小禾原图缓存/f_000056",
          "assetUrl": "assets/notification-mini/template-originals/tpl-126-block-1.png",
          "assetState": "cache-filled",
          "assetSha256": "B33AA7437E64E9BB18F684662C683F9B636FE495D5D385FF688BA9C6123126A0",
          "sourceIncomplete": false,
          "sourceCacheId": "f_000056",
          "sourceDimensions": "322x460",
          "sourceBytes": 23441,
          "cacheFillMethod": "按缓存原图编号顺序直补，未逐项核对"
        },
        {
          "type": "text",
          "role": "",
          "text": "尊敬的家长们：\n\n您好！\n\n衷心感谢您一直以来对我园工作的关心、支持和帮助！今年国庆节和中秋节是同一天，在国庆和中秋假期来临之际，为了让您和孩子能够度过一个充实平安的假期，现将放假时间安排及注意事项通知如下，敬请家长配合做好孩子的监护、教育工作！\n\n放假时间：x月x日（周x）—x月x日（周x）共x天\n上课时间：x月x日（周x正式上课）",
          "assetRef": "",
          "assetUrl": "",
          "assetState": "not-applicable",
          "assetSha256": "",
          "sourceIncomplete": false
        },
        {
          "type": "image",
          "role": "温馨提示横幅（列车主题）",
          "text": "",
          "assetRef": "亲小禾原图缓存/f_000057",
          "assetUrl": "assets/notification-mini/template-originals/tpl-126-block-3.png",
          "assetState": "cache-filled",
          "assetSha256": "D47E749A32F30876CBCFB926AEF04CA221932456AEA098634B11D1E80957636B",
          "sourceIncomplete": false,
          "sourceCacheId": "f_000057",
          "sourceDimensions": "320x460",
          "sourceBytes": 39783,
          "cacheFillMethod": "按缓存原图编号顺序直补，未逐项核对"
        },
        {
          "type": "text",
          "role": "",
          "text": "为使孩子度过一个祥和健康的节日，我们特作以下温馨提示：\n\n想必爸爸妈妈已安排好了形式多样的放松、娱乐活动，但孩子的健康是您最关注的，也是我们最牵挂的。为了让孩子度过一个愉快、平安、健康、充实的国庆中秋假期，在此我们特做以下温馨提醒，请您密切留意：",
          "assetRef": "",
          "assetUrl": "",
          "assetState": "not-applicable",
          "assetSha256": "",
          "sourceIncomplete": false
        },
        {
          "type": "image",
          "role": "交通安全插图（儿童过斑马线）",
          "text": "",
          "assetRef": "亲小禾原图缓存/f_000058",
          "assetUrl": "assets/notification-mini/template-originals/tpl-126-block-5.png",
          "assetState": "cache-filled",
          "assetSha256": "40DB3C154F00BD2248764294CE3E5A21115A0B2706309045A72B8025CFF34FF7",
          "sourceIncomplete": false,
          "sourceCacheId": "f_000058",
          "sourceDimensions": "320x462",
          "sourceBytes": 26187,
          "cacheFillMethod": "按缓存原图编号顺序直补，未逐项核对"
        },
        {
          "type": "text",
          "role": "",
          "text": "1.利用国庆中秋假期适时对孩子们开展中华民族的文化传统教育，感受节日气氛。\n\n2.注意交通安全，带幼儿外出旅游或走亲访友时，切记“珍爱生命，安全第一”，注意交通安全，遵守交通规则。教育孩子过马路时要小心来往车辆，严禁在马路上追逐、玩耍，幼儿园小朋友严禁骑自行车上路，以防止交通伤亡事故的发生。",
          "assetRef": "",
          "assetUrl": "",
          "assetState": "not-applicable",
          "assetSha256": "",
          "sourceIncomplete": false
        },
        {
          "type": "image",
          "role": "家庭饮食卫生插图",
          "text": "",
          "assetRef": "亲小禾原图缓存/f_000059",
          "assetUrl": "assets/notification-mini/template-originals/tpl-126-block-7.png",
          "assetState": "cache-filled",
          "assetSha256": "4DEEBF5BFD102D67EB7CB89CFAEE72046EA9F4BE0D26F947B8D58367053FF1B2",
          "sourceIncomplete": false,
          "sourceCacheId": "f_000059",
          "sourceDimensions": "320x460",
          "sourceBytes": 50967,
          "cacheFillMethod": "按缓存原图编号顺序直补，未逐项核对"
        },
        {
          "type": "text",
          "role": "",
          "text": "3.请家长做好孩子个人卫生，防止传染病流行，帮助幼儿养成良好的卫生习惯。\n\n4.新入园的幼儿，家长应提供孩子自己做事的机会，多讲幼儿园发生的事情，避免长假过后幼儿的情绪不稳定。\n\n5.合家团圆或亲朋好友聚餐时，不要让孩子吃生、冷、硬的食品，更不要暴饮暴食。水果和零食也不能多吃，以免引起孩子的肠胃不适。\n\n以上事项，请各位家长积极支持并配合做到，希望我们家园携手，让孩子平安过节，快乐、健康地成长！",
          "assetRef": "",
          "assetUrl": "",
          "assetState": "not-applicable",
          "assetSha256": "",
          "sourceIncomplete": false
        }
      ],
