          "text": "亲爱的家长朋友：\n\n为了萌发宝贝们热爱祖国，尊敬国旗cn的情感，和宣传安全教育的活动，我们每周都会举行升国旗仪式，并在国旗下进行安全教育的宣传。\n\n本学期我们的升旗仪式有了很大的改进与提升，望各位家长能配合幼儿园，帮助幼儿从小养成，热爱祖国，尊敬国旗CN的情怀。于每周一让宝贝们穿校服，以饱满的精神面貌，整齐的服饰，严肃的对待升旗仪式。",
