          "type": "text",
          "role": "",
          "text": "亲爱的家长朋友：\n\n因 xx 地区疫情持续蔓延，为保证全体师生生命安全，防止疫情在校内传播，按照省教育厅紧急通知要求，我园自xx月xx日起暂停线下教学活动，具体返园时间安排另行通知。\n\n各位家长提前把幼儿安排好，并请坚持做好幼儿、幼儿家庭成员健康打卡以及其他上报工作！\n\n假期延续。但我们的爱仍在继续💕，相信祖国的强大。驱散疫情阴霾早日国泰民安。感谢各位家长理解支持配合，生命安全第一位，一切为了幼儿的健康！",
