          "text": "亲爱的家长朋友：\n\n你们好！\n\n幼儿的安全教育一直是我们的重中之重，为进一步加强幼儿园森林防火安全教育工作，我们需要您的支持与配合！\n\n当前天气干燥，气温快速回升，森林火险等级居高不下，倡导有益生态环境保护方式，我们应该这样做：",
