      "id": "067",
      "title": "春季预防过敏通知",
      "category": "健康安全",
      "categoryIndex": 4,
      "cover": "assets/notification-mini/covers/tpl-067.png",
      "articleCoverRef": "059_冬季防冻温馨提示/059-hero-banner.png",
      "sourceStatus": "已确认详情编辑内容与ID059相同；单独保留本卡片和封面；文章内容原图可共享；待当前UI复核",
      "sourceNotes": [
        "V17_e059_0–3与e067_0–3逐帧SHA-256完全一致；V17_d059与d067展示相同的春季过敏文章和相同图文顺序，仅时间戳不同。ID067卡片标题与详情标题一致。",
        "内容块、详情文章封面和正文原图复用ID059；ID067自身列表卡片封面仍独立保留。ID059卡片错配为“冬季防冻温馨提示”的记录不影响本卡片标题。"
      ],
      "sourceUiVerification": null,
      "sourceCardFrame": "V17_card_067.png",
      "blocks": [
        {
          "type": "image",
          "role": "正文标题图片（春季预防过敏通知字样）",
          "text": "",
          "assetRef": "亲小禾原图缓存/f_0000dd",
          "assetUrl": "assets/notification-mini/template-originals/tpl-067-block-1.png",
          "assetState": "cache-filled",
          "assetSha256": "498F6438184EB87B8B755139D8AACBA28B7AF481A2A1AA5BF3B937ED36DE4BE9",
          "sourceIncomplete": false,
          "sourceCacheId": "f_0000dd",
          "sourceDimensions": "558x420",
          "sourceBytes": 226785,
          "cacheFillMethod": "按缓存原图编号顺序直补，未逐项核对"
        },
        {
          "type": "text",
          "role": "",
          "text": "随着气温☀️的升高，各种花🌸也开了，很多家长喜欢趁着春暖花开🌱带着孩子出游踏青🌳，既能让孩子接触大自然🌲，还能增进亲子感情💗。\n\n但对于有的孩子👶来说却无法享受这样的旅程，因为他们花粉💐过敏。过敏是春季高发疾病🤧，一旦发作就可能会出现皮肤干痒、长红斑、喷嚏不断、哮喘发作等各种问题🚨。",
          "assetRef": "",
          "assetUrl": "",
          "assetState": "not-applicable",
          "assetSha256": "",
          "sourceIncomplete": false
        },
        {
          "type": "image",
          "role": "正文插图（幼儿出现花粉过敏）",
          "text": "",
          "assetRef": "亲小禾原图缓存/f_0000de",
          "assetUrl": "assets/notification-mini/template-originals/tpl-067-block-3.png",
          "assetState": "cache-filled",
          "assetSha256": "47CCB7453A80D0EEEFAE82FECBD9DD45A73DD9A219522707743CBB68D364EF65",
          "sourceIncomplete": false,
          "sourceCacheId": "f_0000de",
          "sourceDimensions": "558x420",
          "sourceBytes": 186194,
          "cacheFillMethod": "按缓存原图编号顺序直补，未逐项核对"
        },
        {
          "type": "text",
          "role": "",
          "text": "①为什么春季更容易过敏❓\n引起幼儿过敏的原因主要有两个方面：\n▪ 一是体质因素，即幼儿本身是过敏性体质；\n▪ 二是外在的环境因素，即幼儿接触了过敏原。\n春季天气转暖🌞，宝宝户外活动增多🏀，因而他们接触到过敏原的几率也大大增加。此外，春天又是植物🌱传粉的季节，空气中漂浮着大量花粉、灰尘，幼儿吸入后便极易引发过敏现象🤧。因此，过敏体质幼儿在春季更容易过敏❗\n\n②过敏体质幼儿警惕4类常见过敏原❗\n如果已经知道幼儿是过敏体质，家长在日常生活中应该注意让幼儿避免接触以下👇4类常见过敏原。\n\n🤧吸入性过敏：如花粉、尘螨、灰尘、真菌、动物皮毛、羽毛、寒冷的空气等。\n🍚食物过敏：如牛奶、鸡蛋、海鲜等。牛奶过敏比较常见于新生儿，通常表现为湿疹、腹痛、便秘、腹泻甚至呕吐等症状。\n🧴接触性过敏：如化妆品、油漆、酒精、药膏等。\n💊药物过敏：药物过敏比较少见。一般来说，药物引起的过敏大都会有发热现象，一旦停用引起过敏的药物，体温就会下降。",
          "assetRef": "",
          "assetUrl": "",
          "assetState": "not-applicable",
          "assetSha256": "",
          "sourceIncomplete": false
        },
        {
          "type": "image",
          "role": "尾部叶片和小花装饰",
          "text": "",
          "assetRef": "亲小禾原图缓存/f_0000df",
          "assetUrl": "assets/notification-mini/template-originals/tpl-067-block-5.png",
          "assetState": "cache-filled",
          "assetSha256": "1CBC9AFA41EABBA12BF23BB92F7EC1B2E6BD64A04EDAC27E2855841DAD3E3CEF",
          "sourceIncomplete": false,
          "sourceCacheId": "f_0000df",
          "sourceDimensions": "558x420",
          "sourceBytes": 204365,
          "cacheFillMethod": "按缓存原图编号顺序直补，未逐项核对"
        }
      ],
