          "text": "亲爱的大朋友、小朋友们：\n\n大家好！\n\n4月7日是“世界卫生日”，我国宣传的主题是：巩固全面小康，促进健康公平。我园各班级教师借此机会带领小朋友们开展“世界卫生日”相关主题活动，让宝贝们知道健康最重要，要从小讲卫生。",
