      "id": "082",
      "title": "世界粮食日｜珍惜粮食，拒绝浪费",
      "category": "节日活动",
      "categoryIndex": 5,
      "cover": "assets/notification-mini/covers/tpl-082.png",
      "articleCoverRef": "082_世界粮食日｜珍惜粮食，拒绝浪费/082-hero-banner.png",
      "sourceStatus": "历史详情全文与1块文字正文已转录；顶部金黄田野横幅原图待匹配；待当前UI复核",
      "sourceNotes": [
        "V17_d082_0–1显示全文；e082_0确认正文为1块文字。顶部金色粮田与鸡舍场景作为文章横幅。",
        "卡片标题使用全角“｜”；详情标题按页面可见字符记录为空格加半角“|”。"
      ],
      "sourceUiVerification": null,
      "sourceCardFrame": "V17_card_082.png",
      "blocks": [
        {
          "type": "text",
          "role": "",
          "text": "亲爱的大小朋友：\n\n大家好！\n\n今天是10月16日——世界粮食日（World Food Day，缩写为WFD），是世界各国每年在10月16日围绕发展粮食和农业生产举办纪念活动的日子。今年世界粮食日的主题为：不让任何人掉队。更好生产、更好营养、更好环境、更好生活。\n\n老师在这里向班级小朋友提出倡议：做个爱惜粮食的好宝宝，从自己做起，从珍惜每一粒粮食开始，点菜适量，吃饱为宜。珍惜时光，全部“食”光，拒绝浪费，争当“光盘行动”的示范者。\n\n让我们身体力行，珍惜来之不易的每一粒粮食。",
          "assetRef": "",
          "assetUrl": "",
          "assetState": "not-applicable",
          "assetSha256": "",
          "sourceIncomplete": false
        }
      ],
