      "articleCoverSha256": "A9C071DDA82CD36CCA69F033FC8B32DAD057C89E7FE0D3509864B173E97FC8D1",
      "articleCoverSourceCacheId": "f_0000f7",
      "articleCoverMatchScore": 2.272,
      "articleCoverState": "cache-card-match-unverified"
