      "sourceNotes": [
        "d095_0–5/e095_0–2确认冬至汤圆插图→节日介绍文字→冬至主题海报→活动目标、活动内容及温馨提示4块顺序；顶部雪林背景单列为文章横幅。",
        "按画面保留“时于每年公历12月22日”“长线面”“「线上冬至活动」”等原文表述。"
      ],
      "sourceUiVerification": null,
      "sourceCardFrame": "V17_card_095.png",
      "blocks": [
        {
          "type": "image",
          "role": "正文插图（冬至汤圆与梅花）",
          "text": "",
          "assetRef": "亲小禾原图缓存/f_000115",
          "assetUrl": "assets/notification-mini/template-originals/tpl-095-block-1.png",
          "assetState": "cache-filled",
          "assetSha256": "CD923EE39178929EE765A3A927152CDD4A122A9BE650796CC2E6B86444A77BF0",
          "sourceIncomplete": false,
          "sourceCacheId": "f_000115",
          "sourceDimensions": "837x630",
          "sourceBytes": 486935,
          "cacheFillMethod": "按缓存原图编号顺序直补，未逐项核对"
        },
        {
          "type": "text",
          "role": "",
          "text": "亲爱的大朋友们：\n\n大家好！\n\n为了让幼儿在生活实践中体验民间习俗，感受我国传统文化的丰富内涵。同时通过这样一个节日，更好地培养幼儿的动手动脑能力、丰富他们的生活经验。幼儿园于明日开展「线上冬至活动」。\n\n明天就要到冬至啦，冬至，又称“冬节”、“贺冬”，时于每年公历12月22日，是二十四节气中一个重要的节气。冬至这一天北半球全年中白天最短、黑夜最长。那宝贝们知道冬至这天，我们有什么习俗？北方地区有吃饺子、吃馄饨的风俗，南方地区则有吃汤圆、长线面的习惯。",
          "assetRef": "",
          "assetUrl": "",
          "assetState": "not-applicable",
          "assetSha256": "",
          "sourceIncomplete": false
        },
        {
          "type": "image",
          "role": "正文插图（冬至主题海报：汤圆、饺子与节气文字）",
          "text": "",
          "assetRef": "亲小禾原图缓存/f_000116",
          "assetUrl": "assets/notification-mini/template-originals/tpl-095-block-3.png",
          "assetState": "cache-filled",
          "assetSha256": "2E50298F8E7C8A10E27A6029154E252BC81FC4AC7D582DE0713A91DB0D99302F",
          "sourceIncomplete": false,
          "sourceCacheId": "f_000116",
          "sourceDimensions": "837x630",
          "sourceBytes": 458514,
          "cacheFillMethod": "按缓存原图编号顺序直补，未逐项核对"
        },
        {
          "type": "text",
          "role": "",
          "text": "一、活动目标\n1、认识我国传统的冬至节，知道冬至的由来。\n\n2、了解冬至的传统习俗。\n\n二、活动内容\n1、今天大朋友们可以提前去超市购买一些食材。\n\n2、明天宝贝们可以和家长一起动手包饺子/汤圆，了解中华民族传统习俗，培养宝贝们的动手能力。\n\n【温馨提示】\n大家记得把包饺子/汤圆和准备食材的过程拍照片或者视频及时记录下来哦！！",
          "assetRef": "",
          "assetUrl": "",
          "assetState": "not-applicable",
          "assetSha256": "",
          "sourceIncomplete": false
        }
      ],
